      SCOPED_TRACE(::testing::Message() << "trial " << i << ", a=" << a);
      if (R.is_zero(a)) continue;
      R.power(b, a, -2);
      R.power(c, a, 2);
      R.mult(c, b, c);
      EXPECT_TRUE(almostEqual(R, nbits - 4, c, 1.0));
    }
}

