TEST(ARingRRi, subtract)
{
  M2::ARingRRi R(100);
  M2::ARingRRR S(100);
  ARingElementGenerator<M2::ARingRRi> gen(R);
  M2::ARingRRi::ElementType a, b, c, e;
  R.init(a);
  R.init(b);
  R.init(c);
  R.init(e);

  M2::ARingRRR::ElementType f;
  S.init(f);
  for (int i = 0; i < ntrials; i++)
    {
