      R.add(e, c, b);  // should be a
      EXPECT_TRUE(R.is_subset(a,e));
      R.mult(e, a, b);
      R.subtract_multiple(e, a, b);
      R.midpoint(f,e);
      EXPECT_TRUE(S.is_zero(f));
    }
  S.clear(f);
  R.clear(e);
  R.clear(c);
  R.clear(b);
