// Copyright 2026, The Macaulay2 Authors.

#include "unit-tests/RingElem.hpp"

#include <gmpxx.h>

#include <algorithm>
#include <string>
#include <vector>
#include "BasicPoly.hpp"
#include "rings/polyring.hpp"
#include "monoid.hpp"

// Convert a BasicPoly (parsed polynomial with mpz_class coefficients and
// varpower monomials) into a ring_elem in the given PolynomialRing.
static ring_elem basicPolyToRingElem(const PolynomialRing *P,
                                     const BasicPoly &bp)
{
  const Ring *K = P->getCoefficients();
  const Monoid *M = P->getMonoid();
  int nvars = M->n_vars();

  ring_elem result = P->from_long(0);
  std::vector<int> exp(nvars, 0);
  monomial monom = M->make_one();

  int monomStart = 0;
  for (size_t i = 0; i < bp.mCoefficients.size(); ++i)
    {
      // Convert coefficient: mpz_class -> ring_elem in coefficient ring
      ring_elem coeff = K->from_int(bp.mCoefficients[i].get_mpz_t());

      // Convert monomial: varpower format -> exponent vector -> encoded
      // monomial
      int monomLen = bp.mMonomials[monomStart];
      std::fill(exp.begin(), exp.end(), 0);
      for (int j = monomStart + 1; j < monomStart + monomLen; j += 2)
        {
          int var = bp.mMonomials[j];
          int e = bp.mMonomials[j + 1];
          if (var >= 0 && var < nvars) exp[var] = e;
        }
      M->from_expvector(exp.data(), monom);

      // Create the term and add it to the result
      ring_elem term = P->make_flat_term(coeff, monom);
      result = P->add(result, term);

      monomStart += monomLen;
    }

  M->remove(monom);
  return result;
}

RingElem RingElem::fromString(const Ring *R, const std::string &s)
{
  // Polynomial rings (including WeylAlgebra, skew, quotient rings, etc.)
  const PolynomialRing *P = R->cast_to_PolynomialRing();
  if (P != nullptr)
    {
      const Monoid *M = P->getMonoid();
      std::vector<std::string> varnames = M->variableNames();
      BasicPoly bp = parseBasicPoly(s, varnames);
      ring_elem result = basicPolyToRingElem(P, bp);
      return RingElem(R, result);
    }

  // Base rings: parse as an integer
  // Works for ZZ, ZZ/p, QQ (integers only), and other rings with from_int
  mpz_class val(s);
  return RingElem(R, R->from_int(val.get_mpz_t()));
}

// Copyright 2026, The Macaulay2 Authors.
//
// RingElem: A lightweight value-semantics wrapper around (const Ring*,
// ring_elem). Unlike RingElement (which is heap-allocated and returns pointers
// from operators), RingElem lives on the stack and operators return values,
// making test code concise:
//
//   auto x = RingElem::var(W, 0);
//   auto Dx = RingElem::var(W, 2);
//   auto one = RingElem::fromInt(W, 1);
//   EXPECT_EQ(Dx * x - x * Dx, one);
//
//   auto f = RingElem::fromString(R, "x^2+3*x*y-1");

#ifndef M2_UNIT_TESTS_RINGELEM_HPP
#define M2_UNIT_TESTS_RINGELEM_HPP

#include <cassert>
#include <iostream>
#include <string>
#include <vector>

#include "buffer.hpp"
#include "rings/ring.hpp"
#include "rings/polyring.hpp"
#include "monoid.hpp"
#include "BasicPoly.hpp"

class RingElem
{
  const Ring *mRing;
  ring_elem mValue;

 public:
  // Primary constructor: wraps a pre-computed ring_elem.
  // Use the static factories below for common cases.
  RingElem(const Ring *R, ring_elem f) : mRing(R), mValue(f) {}

  // Factory: create the i-th variable of the ring
  static RingElem var(const Ring *R, int i) { return RingElem(R, R->var(i)); }

  // Factory: create a ring element from an integer
  static RingElem fromInt(const Ring *R, long n)
  {
    return RingElem(R, R->from_long(n));
  }

  // Factory: create a ring element from a string.
  // For polynomial rings: parses "x^2+3*x*y-1" using variable names from the
  // ring. For base rings (ZZ, ZZ/p): parses an integer. Polynomial syntax
  // errors throw parsing_error; invalid base-ring integers throw
  // std::invalid_argument. NOTE: fromString and toString are not yet inverses
  // of each other. toString outputs e.g. "x3+2xyz" while fromString expects
  // "x^3+2*x*y*z".
  // TODO: make these round-trip compatible.
  // TODO: fromDouble
  static RingElem fromString(const Ring *R, const std::string &s);

  // Accessors
  const Ring *ring() const { return mRing; }
  ring_elem value() const { return mValue; }

  // Predicates
  bool isZero() const { return mRing->is_zero(mValue); }
  bool isUnit() const { return mRing->is_unit(mValue); }

  // Comparison
  bool operator==(const RingElem &b) const
  {
    assert(mRing == b.mRing &&
           "RingElem comparison requires elements from the same ring");
    return mRing->is_equal(mValue, b.mValue);
  }
  bool operator!=(const RingElem &b) const { return !(*this == b); }

  // Arithmetic (returns values, not pointers)
  RingElem operator-() const { return RingElem(mRing, mRing->negate(mValue)); }

  RingElem operator+(const RingElem &b) const
  {
    assert(mRing == b.mRing &&
           "RingElem addition requires elements from the same ring");
    return RingElem(mRing, mRing->add(mValue, b.mValue));
  }

  RingElem operator-(const RingElem &b) const
  {
    assert(mRing == b.mRing &&
           "RingElem subtraction requires elements from the same ring");
    return RingElem(mRing, mRing->subtract(mValue, b.mValue));
  }

  RingElem operator*(const RingElem &b) const
  {
    assert(mRing == b.mRing &&
           "RingElem multiplication requires elements from the same ring");
    return RingElem(mRing, mRing->mult(mValue, b.mValue));
  }

  RingElem operator/(const RingElem &b) const
  {
    assert(mRing == b.mRing &&
           "RingElem division requires elements from the same ring");
    return RingElem(mRing, mRing->divide(mValue, b.mValue));
  }

  // Scalar multiplication
  RingElem operator*(long n) const
  {
    return RingElem(mRing, mRing->mult(mRing->from_long(n), mValue));
  }
  friend RingElem operator*(long n, const RingElem &f) { return f * n; }

  RingElem power(int n) const
  {
    return RingElem(mRing, mRing->power(mValue, n));
  }

  // String output (for gtest diagnostics)
  std::string toString() const
  {
    buffer o;
    mRing->elem_text_out(o, mValue);
    return std::string(o.str());
  }

  friend std::ostream &operator<<(std::ostream &os, const RingElem &f)
  {
    return os << f.toString();
  }
};

#endif

// Copyright 2013 Michael E. Stillman

#include <gtest/gtest.h>

#include "unit-tests/RingTest.hpp"

#include "basic-rings/aring-glue.hpp"
#include "rings/ZZp.hpp"

template <>
ring_elem getElement<RingQQ>(const RingQQ &R, int index)
{
  if (index < 50) return R.from_long(index - 25);
  mpz_t maxH;
  mpz_init_set_str(maxH, "100000000000", 10);
  gmp_QQ a1 = rawRandomQQ(maxH);
  mpz_clear(maxH);
  ring_elem result;
  EXPECT_TRUE(R.from_rational(a1, result));
  return result;
}
TEST(RingQQ, create)
{
  // Construction exposes the expected coefficient type and ring name.
  const Ring *R = globalQQ;
  ASSERT_NE(R, nullptr);

  EXPECT_TRUE(dynamic_cast<const Z_mod *>(R) == nullptr);
  EXPECT_TRUE(dynamic_cast<const RingQQ *>(R) != nullptr);
  EXPECT_EQ(R->coefficient_type(), Ring::COEFF_QQ);
  EXPECT_FALSE(R->is_ZZ());
  EXPECT_EQ(ringName(*R), "QQGMP");
}
TEST(RingQQ, ones)
{
  // Integer coercion agrees with the cached zero and unit constants.
  const Ring *R = globalQQ;
  EXPECT_TRUE(R->is_equal(R->one(), R->from_long(1)));
  EXPECT_TRUE(R->is_equal(R->minus_one(), R->from_long(-1)));
  EXPECT_TRUE(R->is_equal(R->zero(), R->from_long(0)));
  EXPECT_TRUE(R->is_zero(R->from_long(0)));
}
TEST(RingQQ, negate)
{  // Generated values cancel their additive inverses.
  testRingNegate(globalQQ, ntrials);
}
TEST(RingQQ, add)
{  // Adding and then subtracting the same value recovers the input.
  testRingAdd(globalQQ, ntrials);
}
TEST(RingQQ, subtract)
{  // Subtraction is undone by adding the subtrahend.
  testRingSubtract(globalQQ, ntrials);
}
TEST(RingQQ, multDivide)
{  // Exact multiplication/division recovers the original value.
  testRingDivide(globalQQ, ntrials);
}
TEST(RingQQ, axioms)
{  // Generated inputs satisfy the commutative ring identities.
  testRingAxioms(globalQQ, ntrials);
}
TEST(RingQQ, power)
{  // Machine and GMP exponents agree with the power addition law.
  testRingPower(globalQQ, ntrials);
}
TEST(RingQQ, syzygy)
{  // Syzygy coefficients cancel their inputs when the second input is nonzero.
  testRingSyzygy(globalQQ, ntrials);
}
TEST(RingQQ, divisionErrors)
{
  // Zero divisors raise the documented exception for both zero and nonzero
  // numerators.
  const auto *R = globalQQ;
  ASSERT_NE(R, nullptr);
  for (long numerator : {0L, 1L, -3L})
    {
      SCOPED_TRACE(::testing::Message() << "numerator " << numerator);
      EXPECT_THROW(R->divide(R->from_long(numerator), R->zero()),
                   exc::division_by_zero_error);
    }
}

